    expect(consoleWarnSpy).not.toHaveBeenCalled(); // Actually the error is caught in try/catch which logs via console.error
    consoleWarnSpy.mockRestore();
    unmount();
  });

  it('should log warning for non-ServerMessage data', () => {
    const consoleWarnSpy = vi.spyOn(console, 'warn').mockImplementation(() => {});
    const { unmount } = renderHook(() => useWebSocket());
    act(() => {
      currentMockWs!._triggerMessage({ type: 'unknown_type' } as any);
    });
    expect(consoleWarnSpy).toHaveBeenCalledWith(
      'Received invalid message from server',
