/** Register event listeners (used by testing-library or DOM env) */
addEventListener(type: string, fn: EventListenerOrEventListenerObject): void {
  if (type === 'open') this._openListeners.add(fn as () => void);
  else if (type === 'close') this._closeListeners.add(fn as (code?: number, reason?: string) => void);
  else if (type === 'error') this._errorListeners.add(fn as () => void);
  else if (type === 'message') this._messageListeners.add(fn as (data: ServerMessage) => void);
}

removeEventListener(type: string, fn: EventListenerOrEventListenerObject): void {
  if (type === 'open') this._openListeners.delete(fn as () => void);
  else if (type === 'close') this._closeListeners.delete(fn as (code?: number, reason?: string) => void);
  else if (type === 'error') this._errorListeners.delete(fn as () => void);
  else if (type === 'message') this._messageListeners.delete(fn as (data: ServerMessage) => void);
}

